<?php session_start(); require_once __DIR__.'/../config/database.php'; require_role('company'); $data=db_load(); $company=db_company_by_user($data,(int)$_SESSION['user_id']); $cid=(int)($company['id']??0); $error='';$title=$description=$location=$skills=$duration=$stipend=''; if($_SERVER['REQUEST_METHOD']==='POST'){$title=trim($_POST['title']??'');$description=trim($_POST['description']??'');$location=trim($_POST['location']??'');$skills=trim($_POST['skills']??'');$duration=trim($_POST['duration']??'');$stipend=trim($_POST['stipend']??'');if($title===''||$description===''||$location==='')$error='Please complete the title, description and location.';else{$data['internships'][]=['id'=>db_next_id($data,'internships'),'company_id'=>$cid,'title'=>$title,'description'=>$description,'location'=>$location,'skills'=>$skills,'duration'=>$duration,'stipend'=>$stipend,'status'=>'Open','created_at'=>db_now()];if(db_save($data)){flash('success','Internship published successfully.');header('Location: internships.php');exit;}else $error='Unable to save the internship.';}} ?>
<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Post Internship · Arti Vaniyar Internships Hub</title><link rel="stylesheet" href="../css/style.css"></head><body><?php include 'company_nav.php'; ?><main class="dashboard narrow"><div class="page-heading"><div><p class="eyebrow">NEW OPPORTUNITY</p><h1>Post an internship.</h1><p>Give students the information they need to apply confidently.</p></div></div><?php if($error): ?><div class="alert error"><?=e($error)?></div><?php endif; ?><div class="form-card"><form method="POST"><label>Internship title *</label><input name="title" value="<?=e($title)?>" placeholder="e.g. Full Stack Developer Intern" required><label>Description *</label><textarea name="description" rows="7" placeholder="Responsibilities, requirements and what the intern will learn..." required><?=e($description)?></textarea><div class="form-grid"><div><label>Location *</label><input name="location" value="<?=e($location)?>" placeholder="Chennai / Remote" required></div><div><label>Skills</label><input name="skills" value="<?=e($skills)?>" placeholder="PHP, MySQL, JavaScript"></div><div><label>Duration</label><input name="duration" value="<?=e($duration)?>" placeholder="3 months"></div><div><label>Stipend</label><input name="stipend" value="<?=e($stipend)?>" placeholder="₹10,000 / month"></div></div><button class="btn primary" type="submit">Publish internship</button></form></div></main></body></html>
